{"sql": "-- Create the employee_performance_analysis table
DROP TABLE IF EXISTS employees.employee_performance_analysis;

CREATE TABLE employees.employee_performance_analysis (
    employee_id bigint,
    performance_category varchar(50),
    salary_growth_rate decimal(10,2),
    days_of_service integer,
    promotion_count integer
);"}

{"sql": "-- Create the department_salary_analysis table
DROP TABLE IF EXISTS employees.department_salary_analysis;

CREATE TABLE employees.department_salary_analysis (
    department_name varchar(100),
    avg_current_salary decimal(12,2),
    employee_count integer,
    salary_range_spread integer
);"}
